"""The X3DUOM facts R2R reasons with (data/uom-facts.json, generated by gen_uom.py from the validator fork's copy).

One place answers: is this a node, what type is this field, what range and enumeration does it declare, which abstract
types does the node inherit, which field of the parent would hold this child. Nothing here validates; it only answers.
"""
from __future__ import annotations

import json
from functools import lru_cache
from pathlib import Path

FACTS_PATH = Path(__file__).resolve().parent / "data" / "uom-facts.json"

# attributes every element may carry that are not fields of the node
XML_ATTRS = {"xmlns", "xsd", "noNamespaceSchemaLocation", "schemaLocation", "space", "lang", "base"}


class Facts:
    def __init__(self, raw: dict):
        self.raw = raw
        self.nodes: dict = raw["nodes"]
        self.statements: dict = raw["statements"]
        self.field_types: dict = raw["fieldTypes"]
        self.simple: dict = raw["simpleTypes"]
        self.abstract: dict = raw["abstract"]
        self.source: dict = raw["source"]

    def is_node(self, name: str) -> bool:
        return name in self.nodes

    def known(self, name: str) -> bool:
        return name in self.nodes or name in self.statements

    def isa(self, name: str) -> list[str]:
        n = self.nodes.get(name)
        return n["isa"] if n else []

    def is_a(self, name: str, kind: str) -> bool:
        """True when node `name` is `kind` or inherits it. `kind` may be 'A|B' as the X3DUOM writes acceptable types."""
        kinds = kind.split("|")
        return name in kinds or any(k in self.isa(name) for k in kinds)

    def since(self, name: str) -> str | None:
        n = self.nodes.get(name)
        return n["since"] if n else None

    def field(self, node: str, attr: str) -> dict | None:
        n = self.nodes.get(node) or self.statements.get(node)
        return n["fields"].get(attr) if n else None

    def fields(self, node: str) -> dict:
        n = self.nodes.get(node) or self.statements.get(node)
        return n["fields"] if n else {}

    def default_container(self, node: str) -> str | None:
        n = self.nodes.get(node)
        return n["cf"] if n else None

    def enum(self, frow: dict) -> list[str] | None:
        """The closed list of values a field declares, or None when it declares none or allows additions."""
        st = frow.get("st")
        if not st or frow.get("open") is not False:
            return None
        s = self.simple.get(st)
        return s["values"] if s else None

    def node_fields(self, parent: str) -> dict:
        """The SFNode and MFNode fields of a node: {field: row}."""
        return {k: v for k, v in self.fields(parent).items() if v["t"] in ("SFNode", "MFNode")}

    def accepts(self, parent: str, field: str, child: str) -> bool | None:
        """Does parent.field accept a child of this node type? None when the X3DUOM does not say."""
        row = self.field(parent, field)
        if row is None or row["t"] not in ("SFNode", "MFNode"):
            return False
        acc = row.get("accepts")
        if not acc:
            return None
        return self.is_a(child, acc)


@lru_cache(maxsize=1)
def facts() -> Facts:
    return Facts(json.loads(FACTS_PATH.read_text(encoding="utf-8")))
